INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Zeigt eine solche Struktur immer nur Hierarchien?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch funktionale Beziehungen darstellen"}, {"text": "Ja", "correct": false, "because": "Mehr als Hierarchien möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich eine Unternehmensstruktur visualisiere?', 3, '[{"text": "Klarheit über Verantwortlichkeiten", "correct": true, "because": "Fördert Transparenz"}, {"text": "Maximale Farbvielfalt", "correct": false, "because": "Nicht relevant"}, {"text": "Minimale Linien", "correct": false, "because": "Klarheit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise zu einer solchen Darstellung?', 5, '[{"text": "Abteilungen", "correct": true, "because": "Zeigen Organisationseinheiten"}, {"text": "Rollen", "correct": true, "because": "Definieren Verantwortlichkeiten"}, {"text": "Farbcodes", "correct": false, "because": "Nur gestalterisch"}, {"text": "Produktkataloge", "correct": false, "because": "Nicht strukturrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine solche Darstellung zeigt Berichtslinien. b) Sie ersetzt Prozessdokumentationen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist eine andere Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine solche Struktur erstelle?', 4, '[{"text": "Hierarchieebenen", "correct": false, "because": "Kern der Darstellung"}, {"text": "Kommunikationswege", "correct": false, "because": "Wichtig für Klarheit"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Organisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Darstellung immer top-down ist?', 2, '[{"text": "Nein", "correct": true, "because": "Matrixformen sind möglich"}, {"text": "Ja", "correct": false, "because": "Nicht immer hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für die Lesbarkeit entscheidend?', 3, '[{"text": "Klare Beschriftung", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Hohe Farbdichte", "correct": false, "because": "Kann ablenken"}, {"text": "Komplexe Verknüpfungen", "correct": false, "because": "Verwirrt oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine solche Visualisierung?', 5, '[{"text": "Übersicht über Strukturen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Identifikation von Verantwortlichen", "correct": true, "because": "Klärt Zuständigkeiten"}, {"text": "Produktinformationen", "correct": false, "because": "Nicht relevant"}, {"text": "Finanzdaten", "correct": false, "because": "Andere Dokumente"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Strukturen helfen bei der Einarbeitung. b) Sie zeigen Arbeitsabläufe. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Prozesssache"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine solche Darstellung?', 4, '[{"text": "Rollenbeschreibungen", "correct": false, "because": "Klären Aufgaben"}, {"text": "Hierarchie", "correct": false, "because": "Zeigt Struktur"}, {"text": "Mitarbeiterfotos", "correct": true, "because": "Nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine solche Darstellung nur für große Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Teams nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Strukturen kann ich so darstellen?', 4, '[{"text": "Hierarchisch", "correct": true, "because": "Klassische Top-Down-Form"}, {"text": "Matrix", "correct": true, "because": "Zeigt funktionale Beziehungen"}, {"text": "Finanzflüsse", "correct": false, "because": "Andere Visualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Darstellungen immer veraltet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Aktuell bei Pflege"}, {"text": "Ja", "correct": false, "because": "Hängt von Wartung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung einer solchen Übersicht?', 3, '[{"text": "Aktualität", "correct": true, "because": "Sichert Relevanz"}, {"text": "Detailtiefe", "correct": false, "because": "Kann überladen"}, {"text": "Farbschema", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Strukturen klären Berichtslinien. b) Sie ersetzen Stellenbeschreibungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist detaillierter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen bei der Erstellung solcher Übersichten?', 5, '[{"text": "Diagrammsoftware", "correct": true, "because": "Wie Visio oder Lucidchart"}, {"text": "Workflow-Tools", "correct": true, "because": "Unterstützen Strukturierung"}, {"text": "Texteditoren", "correct": false, "because": "Weniger geeignet"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht optimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer solchen Darstellung unwichtig?', 3, '[{"text": "Abteilungsstruktur", "correct": false, "because": "Kern der Darstellung"}, {"text": "Verantwortlichkeiten", "correct": false, "because": "Definiert Rollen"}, {"text": "Schriftarten", "correct": true, "because": "Nur gestalterisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt eine solche Darstellung auch Prozesse?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Struktur, nicht Abläufe"}, {"text": "Ja", "correct": false, "because": "Prozesse sind separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Übersicht für Projektteams nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Klärt temporäre Rollen"}, {"text": "Nein", "correct": false, "because": "Auch für Projekte relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Nutzung einer solchen Darstellung?', 4, '[{"text": "Neue Mitarbeiter einarbeiten", "correct": true, "because": "Zeigt Struktur klar"}, {"text": "Produktentwicklung", "correct": false, "because": "Andere Dokumentation"}, {"text": "Serverwartung", "correct": false, "because": "Technische Aufgabe"}]');
